'use strict';

// MODULES //

var max = require( '@stdlib/math/base/special/max' );


// VARIABLES //

/**
* Weight decay functions, indexed by penalty enumeration constant.
*
* @private
* @name DECAYS
* @constant
* @type {Array}
*
* @example
* var f = DECAYS[ 2 ];
* // returns <Function>
*/
var DECAYS = [
	l2Decay,       // 0: elasticnet
	identityDecay, // 1: l1
	l2Decay,       // 2: l2
	identityDecay  // 3: none
];


// FUNCTIONS //

/**
* Computes scale factor by applying the identity decay.
*
* Note:
*
* -   Here `params` => `[ ]` (empty)
*
* @private
* @param {NonNegativeInteger} scaleFactor - current iteration.
* @param {NonNegativeInteger} eta - learning rate.
* @param {Float64Array} params - strided array containing regularizer specific parameters.
* @returns {number} scale factor
*/
function identityDecay( scaleFactor, eta, params ) { // eslint-disable-line no-unused-vars
	return scaleFactor;
}

/**
* Computes scale factor by applying the L2 decay.
*
* Note:
*
* -   Here `params` => `[ eta, lambda, l1Ratio ]`
*
* @private
* @param {NonNegativeInteger} scaleFactor - current iteration.
* @param {NonNegativeInteger} eta - learning rate.
* @param {Float64Array} params - strided array containing regularizer specific parameters.
* @returns {number} scale factor
*/
function l2Decay( scaleFactor, eta, params ) {
	return scaleFactor * max( 0.0, 1.0 - ( ( 1.0 - params[ 2 ] ) * eta * params[ 1 ] ) ); // eslint-disable-line max-len
}


// EXPORTS //

module.exports = DECAYS;
